namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Abbreviation = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Abbreviation = "HIST", Description = "Study of past events and their impact on society." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She specializes in programming languages and pedagogy.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez is a researcher in algorithm optimization with publications in top-tier conferences. He brings real-world problem-solving into the classroom.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS 310", Title = "Database Systems", Description = "Design and implementation of database systems. Covers relational model, SQL, normalization, indexing, and transaction management.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", InstructorName = "Dr. Carol Wang", InstructorBio = "Dr. Wang worked in industry for a decade building large-scale distributed databases before joining academia." },
            new() { Id = 4, DepartmentId = 2, CourseCode = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is an award-winning mathematics educator known for making abstract concepts accessible.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 252", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:30 PM", InstructorName = "Dr. Emily Novak", InstructorBio = "Dr. Novak researches applied linear algebra in machine learning and data science." },
            new() { Id = 6, DepartmentId = 3, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments.", Credits = 4, Schedule = "Tue/Thu 9:00–10:30 AM + Lab Fri 1:00–3:00 PM", InstructorName = "Dr. Frank Okafor", InstructorBio = "Dr. Okafor is an experimental physicist with expertise in condensed matter physics and science communication." },
            new() { Id = 7, DepartmentId = 3, CourseCode = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Grace Liu", InstructorBio = "Dr. Liu is a theoretical physicist specializing in quantum electrodynamics." },
            new() { Id = 8, DepartmentId = 4, CourseCode = "ENG 110", Title = "College Composition", Description = "Development of writing skills through essay composition, research methods, and critical analysis of texts.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Prof. Hannah Brooks", InstructorBio = "Prof. Brooks is a published author and writing coach with expertise in academic and creative writing.", IsFeatured = true },
            new() { Id = 9, DepartmentId = 4, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, examining themes of identity, freedom, and social change.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", InstructorName = "Dr. Ian Goldstein", InstructorBio = "Dr. Goldstein is a literary critic specializing in 20th-century American fiction." },
            new() { Id = 10, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from antiquity through the medieval period, covering political, social, and cultural developments.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:30 PM", InstructorName = "Dr. Julia Ramirez", InstructorBio = "Dr. Ramirez is a historian of ancient and medieval civilizations with extensive fieldwork experience." },
            new() { Id = 11, DepartmentId = 5, CourseCode = "HIST 202", Title = "Modern European History", Description = "Europe from the Enlightenment to the present. Topics include revolutions, industrialization, world wars, and European integration.", Credits = 3, Schedule = "Mon/Wed 10:00–11:30 AM", InstructorName = "Dr. Karl Weber", InstructorBio = "Dr. Weber specializes in modern European political history and has authored several books on 20th-century Europe." }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public string GetDepartmentName(int departmentId) =>
        _departments.FirstOrDefault(d => d.Id == departmentId)?.Name ?? "Unknown";

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

